function verticalMetricText(value,suffix='%'){return`${value>=0?'+':'−'}${Math.abs(value).toFixed(2)}${suffix}`}
function verticalItemsForGroup(){const names=groupMembers[currentVerticalGroup]||Object.keys(stocks);return names.map(name=>originalWatchRows.find(item=>item.name===name)).filter(Boolean)}
function updateVerticalSummary(){const items=verticalItemsForGroup(),average=items.reduce((sum,item)=>sum+item.pct,0)/Math.max(1,items.length),up=items.filter(item=>item.pct>0).length,down=items.filter(item=>item.pct<0).length,amount=items.reduce((sum,item)=>sum+item.amountNumber,0);$('#vertical-average').textContent=verticalMetricText(average);$('#vertical-average').className=average>=0?'up':'down';$('#vertical-up').textContent=`${up} 涨`;$('#vertical-down').textContent=`${down} 跌`;$('#vertical-amount').textContent=`${amount.toFixed(1)} 亿`}
function renderVerticalList(){
  let items=verticalItemsForGroup().filter(item=>!verticalQuery||`${item.name}${stocks[item.name].code}${stocks[item.name].conclusion}`.toLowerCase().includes(verticalQuery));
  if(verticalSort==='pct')items.sort((a,b)=>b.pct-a.pct);else if(verticalSort==='amount')items.sort((a,b)=>b.amountNumber-a.amountNumber);else if(verticalSort==='since')items.sort((a,b)=>b.sinceNumber-a.sinceNumber);else if(verticalSort==='turnover')items.sort((a,b)=>parseFloat(b.turnover)-parseFloat(a.turnover));
  const list=$('#watch-table-body');list.innerHTML=items.map(item=>{const stock=stocks[item.name],stateClass=stock.status==='已完成'?'done':stock.status==='待研究'?'todo':'none',currency=stock.code.includes('HK')?'HK$ ':stock.code.includes('US')?'$ ':'¥ ';return`<button class="vertical-stock-row${item.name===activeStock?' selected':''}" data-stock="${item.name}"><div class="vertical-stock-top"><div class="vertical-stock-name"><strong>${item.name}</strong><small>${stock.code.split(' · ')[0]}</small></div><span class="vertical-stock-price">${currency}${stock.price}</span></div><div class="vertical-stock-second"><span><span class="research-state ${stateClass}">${stock.status}</span></span><span class="vertical-stock-changes"><span class="${stock.dir}">${verticalMetricText(item.pct)}</span><span class="v-since ${item.sinceNumber>=0?'up':'down'}">入组 ${item.since}</span></span></div><div class="vertical-stock-third"><div class="sparkline ${stock.dir==='up'?'up-line':'down-line'}" data-spark="${item.spark}"></div><span class="v-conclusion">${stock.conclusion}</span></div><div class="vertical-stock-metrics"><span class="v-amount">额 ${item.amount}</span><span class="v-delta ${item.deltaNumber>=0?'up':'down'}">昨日 ${item.delta}</span><span class="v-turnover">换 ${item.turnover}</span></div></button>`}).join('')||'<div class="vertical-list-empty">没有匹配的股票</div>';
  $$('.vertical-stock-row',list).forEach(row=>row.addEventListener('click',()=>selectStock(row.dataset.stock)));$('#vertical-visible-count').textContent=`${items.length} 只显示 · 共 ${verticalItemsForGroup().length} 只`;renderSparklines();
}
